Convex 1.44.0. A reachable HTTP endpoint returns valid JSON. A client invokes each of these functions through its matching API (query, mutation or action).

convex/index.ts
```ts
import { query, mutation, action } from "./_generated/server";
import { v } from "convex/values";
const definition = {
  args: { url: v.string() },
  handler: async (_ctx: unknown, args: { url: string }) => {
    const response = await fetch(args.url);
    return await response.json();
  },
};
export const read = query(definition);
export const write = mutation(definition);
export const request = action(definition);
```
